import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Vector3 } = ctx.THREE;
  const group = new Group();

  // ---------- Gradient Backdrop ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial();
  const gradStops = (config?.intent?.visualSpec?.colors?.gradientStops ||
    config?.visualSpec?.colors?.gradientStops ||
    [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#12121a' }]);

  const col0 = color(gradStops[0].hex);
  const col1 = color(gradStops[1].hex);
  backdropMat.colorNode = mix(col0, col1, uv().y);
  backdropMat.roughness = 0.8;
  backdropMat.metalness = 0.0;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // ---------- Text Content ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((i) => i.role === 'headline') || { text: 'The collection' };
  const bodyItem = textItems.find((i) => i.role === 'body') || { text: 'Five calibres. One discipline.' };
  const captionItems = textItems.filter((i) => i.role === 'caption');

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  group.add(headline);

  const body = ctx.fontAtlas.createText(bodyItem.text, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0);
  group.add(body);

  // ---------- Filmstrip ----------
  const strip = new Group();
  strip.rotation.y = -Math.PI * 18 / 180; // -18 degrees
  group.add(strip);

  const pitch = 1.85;
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const bevelSize = 0.025;
  const focusIndex = 2; // centered card
  const textureUrl = config.imageUrl || config.meshUrl || '';

  // Load texture once (shared)
  const texturePromise = textureUrl
    ? ctx.textureLoader.loadTexture(textureUrl)
    : Promise.resolve(null);

  const cardGroupArray = [];

  for (let i = 0; i < 5; i++) {
    const cardGroup = new Group();
    const xPos = (i - focusIndex) * pitch;
    cardGroup.position.x = xPos;
    strip.add(cardGroup);
    cardGroupArray.push(cardGroup);

    // Frame (bevel) geometry
    const frameGeo = new BoxGeometry(cardWidth + bevelSize * 2, cardHeight + bevelSize * 2, 0.02);
    const frameMat = new MeshStandardNodeMaterial({
      color: '#16161d',
      roughness: 0.8,
      metalness: 0.0,
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = 0.01; // slight forward
    cardGroup.add(frame);

    // Card plane
    const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
    });
    const card = new Mesh(cardGeo, cardMat);
    card.position.z = 0.02;
    cardGroup.add(card);

    // Apply opacity and scale based on focus
    const dist = Math.abs(i - focusIndex);
    const opacity = 1 - dist * 0.225; // 0 -> 1.0, 2 -> 0.55
    cardMat.transparent = true;
    cardMat.opacity = opacity;
    const scale = i === focusIndex ? 1.0 : 0.92;
    cardGroup.scale.set(scale, scale, scale);

    // Caption text (if available)
    const captionItem = captionItems[i - focusIndex] || captionItems[i] || null;
    if (captionItem) {
      const caption = ctx.fontAtlas.createText(captionItem.text, {
        fontSize: 18,
        color: '#e8ecf2',
        align: 'center',
      });
      caption.position.set(0, -cardHeight / 2 - 0.15, 0);
      cardGroup.add(caption);
    }

    // Underline for focused card
    if (i === focusIndex) {
      const underlineGeo = new PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: '#ff2a38',
        emissive: '#ff2a38',
        emissiveIntensity: 1.3,
        roughness: 0.5,
        metalness: 0.0,
      });
      const underline = new Mesh(underlineGeo, underlineMat);
      underline.position.set(0, -cardHeight / 2 - 0.05, 0);
      cardGroup.add(underline);
    }

    // Assign texture when loaded
    texturePromise.then((tex) => {
      if (tex) {
        cardMat.map = tex;
        cardMat.needsUpdate = true;
      }
    });
  }

  // ---------- Cinematic Primitives ----------
  const disposables = {
    textures: [],
    materials: [],
    geometries: [],
    primitives: [],
    timelines: [],
  };

  // Store materials/geometries for cleanup
  disposables.materials.push(backdropMat);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(...cardGroupArray.map(g => g.children[1].material));
  disposables.geometries.push(...cardGroupArray.map(g => g.children[1].geometry));
  disposables.materials.push(...cardGroupArray.map(g => g.children[0].material));
  disposables.geometries.push(...cardGroupArray.map(g => g.children[0].geometry));

  // Apply config.cinematicPrimitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(strip, prim.params || {});
        disposables.primitives.push(instance);
      }
    }
  }

  // Attach empty handlers object
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    // Dispose textures
    disposables.textures.forEach(t => t.dispose && t.dispose());

    // Dispose materials
    disposables.materials.forEach(m => m.dispose && m.dispose());

    // Dispose geometries
    disposables.geometries.forEach(g => g.dispose && g.dispose());

    // Cleanup primitives
    disposables.primitives.forEach(p => p.cleanup && p.cleanup());

    // Kill GSAP timelines
    disposables.timelines.forEach(tl => tl.kill && tl.kill());
  };

  return group;
}
